/** Field count of one split, asserted by the tests so a shape change is noticed. */
export const SPLIT_FIELD_COUNT = 77;

export const transactionListFixture: JsonApiListResponse = {
  data: [singleSplitTransaction, multiSplitTransaction] as unknown as JsonApiListResponse['data'],
  meta: { pagination: { current_page: 1, total_pages: 21, total: 2008 } },
};

export const transactionSingleFixture: JsonApiSingleResponse = {
  data: singleSplitTransaction as unknown as JsonApiSingleResponse['data'],
};

/** Builds `count` list items by cloning the single-split fixture with distinct ids and dates. */
export function makeTransactionList(count: number): JsonApiListResponse {
  const base = singleSplitTransaction as unknown as JsonApiListResponse['data'][number];
  return {
    data: Array.from({ length: count }, (_, i) => ({
      ...base,
      id: String(1000 + i),
      attributes: {
        ...base.attributes,
        transactions: (base.attributes.transactions as Array<Record<string, unknown>>).map((s) => ({
          ...s,
          transaction_journal_id: String(5000 + i),
          date: `2025-0${(i % 9) + 1}-15T12:00:00+01:00`,
        })),
      },
    })),
    meta: { pagination: { current_page: 1, total_pages: 21, total: 2008 } },
  };
}
